function canopyLayers(tree) {
  if (tree.length === 0) return [];
  const nodes = [{ value: tree[0], left: null, right: null }];
  for (let i = 1, head = 0; i < tree.length; head++) {
    const node = nodes[head];
    if (tree[i] !== null) nodes.push(node.left = { value: tree[i], left: null, right: null });
    i++;
    if (i < tree.length && tree[i] !== null) nodes.push(node.right = { value: tree[i], left: null, right: null });
    i++;
  }
  const root = nodes[0];
  const height = (n) => (n ? 1 + Math.max(height(n.left), height(n.right)) : 0);
  const sumAt = (n, d) => (!n ? 0 : d === 0 ? n.value : sumAt(n.left, d - 1) + sumAt(n.right, d - 1));
  const result = [];
  for (let d = 0; d < height(root); d++) result.push(sumAt(root, d));
  return result;
}

function canopyLayers(tree) {
  if (tree.length === 0) return [];
  const nodes = [{ value: tree[0], left: null, right: null }];
  for (let i = 1, head = 0; i < tree.length; head++) {
    const node = nodes[head];
    if (tree[i] !== null) nodes.push(node.left = { value: tree[i], left: null, right: null });
    i++;
    if (i < tree.length && tree[i] !== null) nodes.push(node.right = { value: tree[i], left: null, right: null });
    i++;
  }
  const sums = [];
  let layer = [nodes[0]];
  while (layer.length) {
    let total = 0;
    const next = [];
    for (const node of layer) {
      total += node.value;
      if (node.left) next.push(node.left);
      if (node.right) next.push(node.right);
    }
    sums.push(total);
    layer = next;
  }
  return sums;
}
